@staticmethod
def _verify_synced_presentation_against(
    latest: Dict[Tuple[str, int], Dict[str, Any]],
    presentation: Any,
    challenge: Any,
    source_tenant_id: Optional[str] = None,
) -> Tuple[bool, str]:
    """在已解析的同步锚点快照上验真一条外部演示（只读）。

    假定 presentation 为 JSON 对象、challenge 为非空字符串。未绑定
    形态（source_tenant_id 为 None）的演示字段、挑战、锚点、签名
    格式、验签与期限规则及原因分类与
    :meth:`verify_trust_presentation_synced` 完全一致，供单条与
    批量同步锚点验真共用同一快照。持有者绑定形态
    （source_tenant_id 为非空字符串）演示恰为绑定十二字段，签发者
    与持有者锚点均取同一快照的 (DID, 版本) 末事件，须 active 且
    uses 含 vp；持有者锚点不可用为“同步持有者锚点不可用”，
    holder_proof 覆盖去掉 proof、holder_proof 的对象并加入
    tenant_id=source_tenant_id，格式、验签失败依次为
    “持有者签名格式错误”“持有者签名校验失败”。校验顺序：演示
    字段 -> 挑战 -> 签发锚点/格式/验签 -> 持有者锚点/格式/验签
    （仅绑定）-> 期限。
    """
    # 演示字段（沿用 /v1/trust/presentations/verify 的分类原因）：
    # 未绑定恰为九字段，出现 holder_* 即失败；绑定恰为九字段外加
    # holder_did/holder_key_version/holder_proof。
    is_holder_bound = source_tenant_id is not None
    required_fields = {
        "presentation_id",
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "disclose",
        "claims",
        "challenge",
        "expires_at",
        "proof",
    }
    if is_holder_bound:
        required_fields |= {
            "holder_did",
            "holder_key_version",
            "holder_proof",
        }
    else:
        holder_fields = sorted(
            key for key in presentation if key.startswith("holder_")
        )
        if holder_fields:
            return False, (
                "演示字段不合法: 不得包含持有者绑定字段 "
                f"{', '.join(holder_fields)}"
            )
    if set(presentation) != required_fields:
        missing = sorted(required_fields - set(presentation))
        if missing:
            return False, f"演示缺少字段: {', '.join(missing)}"
        extra = sorted(set(presentation) - required_fields)
        return False, f"演示含多余字段: {', '.join(extra)}"
    for field in ("presentation_id", "credential_id", "issuer_did"):
        value = presentation[field]
        if not isinstance(value, str) or not value:
            return False, f"演示字段 {field} 必须为非空字符串"
    key_version = presentation["issuer_key_version"]
    if (
        not isinstance(key_version, int)
        or isinstance(key_version, bool)
        or key_version < 1
    ):
        return False, "演示字段 issuer_key_version 必须为正整数"
    disclose = presentation["disclose"]
    if not isinstance(disclose, list) or any(
        not isinstance(item, str) for item in disclose
    ):
        return False, "演示字段 disclose 必须为字符串数组"
    if not isinstance(presentation["claims"], dict):
        return False, "演示字段 claims 必须为 JSON 对象"
    for field in ("challenge", "expires_at", "proof"):
        value = presentation[field]
        if not isinstance(value, str) or not value:
            return False, f"演示字段 {field} 必须为非空字符串"
    holder_did_value: Optional[str] = None
    holder_version_value: Optional[int] = None
    holder_proof_value: Optional[str] = None
    if is_holder_bound:
        holder_did_value = presentation["holder_did"]
        if not isinstance(holder_did_value, str) or not holder_did_value:
            return False, "演示字段 holder_did 必须为非空字符串"
        holder_version_value = presentation["holder_key_version"]
        if (
            not isinstance(holder_version_value, int)
            or isinstance(holder_version_value, bool)
            or holder_version_value < 1
        ):
            return False, "演示字段 holder_key_version 必须为正整数"
        holder_proof_value = presentation["holder_proof"]
        if not isinstance(holder_proof_value, str) or not holder_proof_value:
            return False, "演示字段 holder_proof 必须为非空字符串"

    # 挑战：请求 challenge 须等于演示 challenge。
    if challenge != presentation["challenge"]:
        return False, "挑战不匹配: 请求 challenge 与演示 challenge 不一致"

    # 同步锚点：(issuer_did, 版本) 最后事件，须 active 且含 vp 用途。
    issuer_did = presentation["issuer_did"]
    anchor = latest.get((issuer_did, key_version))
    if (
        anchor is None
        or anchor["status"] != "active"
        or "vp" not in anchor["uses"]
    ):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON
    public_pem = anchor["public_key"]
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON

    # 签名格式（严格：64 字节裸 R||S 无填充 base64url）与密码学
    # 验签：覆盖范围沿用 /v1/trust/presentations/verify——去掉
    # proof 及全部 holder_* 字段后的八个字段（未绑定演示本就不含
    # holder_*，即去掉 proof 的全部字段）。
    proof = presentation["proof"]
    message = {
        k: v
        for k, v in presentation.items()
        if k != "proof" and not k.startswith("holder_")
    }
    try:
        crypto.validate_signature_format_strict(proof)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    try:
        crypto.verify(message, proof, public_pem)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    except crypto.InvalidSignature:
        return False, IMPORTED_SIGNATURE_INVALID_REASON
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, IMPORTED_SIGNATURE_INVALID_REASON

    # 持有者绑定：持有者锚点取同一同步快照的 (holder_did, 版本)
    # 末事件，须 active 且含 vp 用途；holder_proof 覆盖去掉
    # proof、holder_proof 的绑定对象并加入
    # tenant_id=source_tenant_id 后规范化验签。
    if is_holder_bound:
        holder_anchor = latest.get((holder_did_value, holder_version_value))
        if (
            holder_anchor is None
            or holder_anchor["status"] != "active"
            or "vp" not in holder_anchor["uses"]
        ):
            return False, SYNCED_HOLDER_ANCHOR_UNAVAILABLE_REASON
        holder_public_pem = holder_anchor["public_key"]
        try:
            crypto.validate_public_key_pem(holder_public_pem)
        except (ValueError, TypeError):
            return False, SYNCED_HOLDER_ANCHOR_UNAVAILABLE_REASON
        holder_message = {
            k: v
            for k, v in presentation.items()
            if k not in ("proof", "holder_proof")
        }
        holder_message["tenant_id"] = source_tenant_id
        try:
            crypto.validate_signature_format_strict(holder_proof_value)
        except crypto.MalformedSignature:
            return False, SYNCED_HOLDER_SIGNATURE_MALFORMED_REASON
        try:
            crypto.verify(
                holder_message, holder_proof_value, holder_public_pem
            )
        except crypto.MalformedSignature:
            return False, SYNCED_HOLDER_SIGNATURE_MALFORMED_REASON
        except crypto.InvalidSignature:
            return False, SYNCED_HOLDER_SIGNATURE_INVALID_REASON
        except Exception:  # noqa: BLE001 验签绝不向上抛错
            return False, SYNCED_HOLDER_SIGNATURE_INVALID_REASON

    # 期限：expires_at 须为 UTC 秒精度 Z 格式；当前时间达到它即
    # 过期。规则同 /v1/trust/presentations/verify。
    expires_value = presentation["expires_at"]
    if (
        not isinstance(expires_value, str)
        or not _UTC_Z_SHAPE_RE.match(expires_value)
    ):
        return False, (
            "演示字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        expires_dt = _parse_utc_z(expires_value)
    except ValueError:
        return False, (
            "演示字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    if datetime.now(timezone.utc) >= expires_dt:
        return False, "演示已过期"
    return True, ""

